function validate([stones]) {
  if (!Array.isArray(stones) || stones.length < 2 || stones.length > 2000) return 'stones needs 2 to 2000 positions.';
  if (stones[0] !== 0) return 'The first stone is at position 0.';
  for (let i = 0; i < stones.length; i++) {
    if (!Number.isInteger(stones[i]) || stones[i] < 0 || stones[i] > 2147483647) return 'Each position is between 0 and 2^31 - 1.';
    if (i > 0 && stones[i] <= stones[i - 1]) return 'stones must be strictly increasing.';
  }
  return null;
}

