function canCross(stones) {
  const n = stones.length;
  const dp = Array.from({ length: n }, () => new Uint8Array(n + 1));
  dp[0][0] = 1;

  for (let i = 1; i < n; i++) {
    for (let j = i - 1; j >= 0; j--) {
      const k = stones[i] - stones[j];
      if (k > j + 1) {
        break;
      }
      if (dp[j][k - 1] || dp[j][k] || dp[j][k + 1]) {
        dp[i][k] = 1;
      }
    }
  }
  return dp[n - 1].includes(1);
}

