function canCross(stones) {
  // Forward search over (position, last jump) states, each visited once.
  const onStone = new Set(stones);
  const last = stones[stones.length - 1];
  const seen = new Set(['0,0']);
  const stack = [[0, 0]];
  while (stack.length) {
    const [pos, jump] = stack.pop();
    if (pos === last) return true;
    for (const step of [jump - 1, jump, jump + 1]) {
      if (step <= 0 || !onStone.has(pos + step)) continue;
      const key = (pos + step) + ',' + step;
      if (!seen.has(key)) { seen.add(key); stack.push([pos + step, step]); }
    }
  }
  return false;
}

