function generate(rand, size) {
  const n = size === 'large' ? 2000 : 2 + Math.floor(rand() * 9);
  const mode = Math.floor(rand() * 3);
  let stones;
  if (mode === 0) {
    // Random gaps: often impossible, sometimes possible.
    stones = [0];
    const maxGap = size === 'large' ? 1 + Math.floor(rand() * 4) : 1 + Math.floor(rand() * 3);
    while (stones.length < n) stones.push(stones[stones.length - 1] + 1 + Math.floor(rand() * maxGap));
  } else {
    // Follow a legal sequence of jumps, then add distractor stones in between.
    const path = [0];
    let jump = 0;
    const count = Math.max(2, Math.floor(n * (0.4 + rand() * 0.5)));
    while (path.length < count) {
      jump = Math.max(1, jump + Math.floor(rand() * 3) - 1);
      if (path.length === 1) jump = 1;
      path.push(path[path.length - 1] + jump);
    }
    const set = new Set(path);
    const end = path[path.length - 1];
    let tries = 0;
    while (set.size < n && tries < 50 * n) {
      tries++;
      const p = 1 + Math.floor(rand() * end);
      if (p < end) set.add(p);
    }
    stones = [...set].sort((a, b) => a - b);
    // Sometimes break the path near the end, or push the last stone far away.
    if (mode === 2 && stones.length > 2) {
      if (rand() < 0.5) stones.splice(stones.length - 2, 1);
      else stones[stones.length - 1] = stones[stones.length - 2] + 1 + Math.floor(rand() * (size === 'large' ? 2147483647 - stones[stones.length - 2] - 1 : 6));
    }
  }
  return [stones];
}
